-- Direct-FK manual actions; no ingestion or historical backfill.
begin;
create function public.line_conversation_action(
 p_id uuid,p_action text,p_version bigint,p_message_ids uuid[],p_case_id text default null,
 p_selected_ids uuid[] default '{}',p_record jsonb default null
) returns jsonb language plpgsql security invoker set search_path=pg_catalog,public as $$
declare c public.line_conversations; actual uuid[]; new_id uuid; target text;
        transcript text; cols text; vals text; changed integer;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  perform pg_advisory_xact_lock(hashtextextended('line_conversations_v1',0));
  select * into c from public.line_conversations where id=p_id for update;
  if not found then raise exception 'Conversation unavailable'; end if;
  select array_agg(id order by id) into actual from public.line_messages where conversation_id=p_id;
  if p_version is null or c.version<>p_version or p_message_ids is null
    or cardinality(actual)<>cardinality(p_message_ids) or not (actual @> p_message_ids and actual <@ p_message_ids)
  then raise exception 'Conversation changed; refresh before processing'; end if;
  if c.status not in ('pending_review','pending','classified','error') then raise exception 'Conversation already processed'; end if;
  perform 1 from public.line_messages where id=any(actual) order by id for update;
  if (select count(*) from public.line_messages where id=any(actual)
      and status=case when c.status='pending_review' then 'pending' else c.status end and case_id is not distinct from c.primary_case_id)<>cardinality(actual)
  then raise exception 'Message workflow changed; refresh before processing'; end if;
  if p_action='split' then
    if cardinality(p_selected_ids)=0 or cardinality(p_selected_ids)>=cardinality(actual)
      or not (actual @> p_selected_ids)
      or cardinality(p_selected_ids)<>(select count(distinct x) from unnest(p_selected_ids) x)
    then raise exception 'Select a nonempty proper subset'; end if;
    insert into public.line_conversations(source,sender_id,sender_name,status,sealed)
      values(c.source,c.sender_id,c.sender_name,c.status,true) returning id into new_id;
    update public.line_messages set conversation_id=new_id
      where conversation_id=p_id and id=any(p_selected_ids);
    get diagnostics changed=row_count;
    if changed<>cardinality(p_selected_ids) then raise exception 'Split membership update denied'; end if;
    update public.line_conversations set sealed=true where id in (p_id,new_id);
    perform public.line_refresh_conversation(p_id);
    perform public.line_refresh_conversation(new_id);
  elsif p_action in ('create','merge','archive') then
    select string_agg(format('[%s] %s',coalesce(m.received_at::text,'time unknown'),m.raw_message),E'\n' order by m.received_at nulls last,m.id)
      into transcript from public.line_messages m where m.id=any(actual);
    if p_action='create' then
      if jsonb_typeof(p_record) is distinct from 'object' or nullif(p_record->>'id','') is null
        or p_record->>'classification_status' is distinct from 'confirmed'
        or coalesce(p_record->>'classification_version','') not in ('v2_2026-09','v3_1_2026-10')
        or nullif(p_record->>'new_product','') is null
        or nullif(p_record->>'case_nature','') is null or nullif(p_record->>'new_category','') is null
        or nullif(p_record->>'new_subcategory','') is null
      then raise exception 'Confirmed V2 case data required'; end if;
      -- Frozen active production V3.1 tuples; refresh alongside dictionary releases.
      if p_record->>'classification_version'='v3_1_2026-10' and (
        not exists(select 1 from jsonb_array_elements($v31$[{"classification_code":"V3-0001","project_name":"FMS","new_product":"GPS","case_nature":"故障/異常","new_category":"GPS車機/通訊","new_subcategory":"GPS設備離線"},{"classification_code":"V3-0004","project_name":"FMS","new_product":"GPS","case_nature":"故障/異常","new_category":"GPS定位/軌跡","new_subcategory":"GPS定位偏移"},{"classification_code":"V3-0005","project_name":"FMS","new_product":"GPS","case_nature":"故障/異常","new_category":"GPS定位/軌跡","new_subcategory":"GPS定位延遲"},{"classification_code":"V3-0006","project_name":"FMS","new_product":"GPS","case_nature":"故障/異常","new_category":"GPS定位/軌跡","new_subcategory":"GPS定位未更新"},{"classification_code":"V3-0007","project_name":"FMS","new_product":"GPS","case_nature":"故障/異常","new_category":"GPS定位/軌跡","new_subcategory":"GPS軌跡缺漏"},{"classification_code":"V3-0008","project_name":"FMS","new_product":"GPS","case_nature":"故障/異常","new_category":"GPS平台資料","new_subcategory":"GPS資料未更新"},{"classification_code":"V3-0009","project_name":"FMS","new_product":"GPS","case_nature":"故障/異常","new_category":"GPS平台資料","new_subcategory":"GPS車輛資料查無"},{"classification_code":"V3-0010","project_name":"FMS","new_product":"GPS","case_nature":"故障/異常","new_category":"GPS報表/API","new_subcategory":"GPS報表資料異常"},{"classification_code":"V3-0011","project_name":"FMS","new_product":"GPS","case_nature":"故障/異常","new_category":"GPS報表/API","new_subcategory":"GPS報表查無資料"},{"classification_code":"V3-0012","project_name":"FMS","new_product":"GPS","case_nature":"故障/異常","new_category":"GPS報表/API","new_subcategory":"GPS報表下載異常"},{"classification_code":"V3-0013","project_name":"FMS","new_product":"GPS","case_nature":"故障/異常","new_category":"GPS報表/API","new_subcategory":"GPS API呼叫異常"},{"classification_code":"V3-0014","project_name":"FMS","new_product":"GPS","case_nature":"故障/異常","new_category":"GPS告警","new_subcategory":"GPS區域告警異常"},{"classification_code":"V3-0015","project_name":"FMS","new_product":"GPS","case_nature":"故障/異常","new_category":"G