se_nature":"故障/異常","new_category":"冷鏈－登入/連線","new_subcategory":"平台無法連線"},{"classification_code":"V3-0195","project_name":"FMS","new_product":"行車視野","case_nature":"故障/異常","new_category":"行車視野－登入/連線","new_subcategory":"平台無法連線"},{"classification_code":"V3-0197","project_name":"FMS","new_product":"冷鏈","case_nature":"故障/異常","new_category":"冷鏈－登入/連線","new_subcategory":"平台無法登入"},{"classification_code":"V3-0198","project_name":"FMS","new_product":"GPS","case_nature":"故障/異常","new_category":"GPS－登入/連線","new_subcategory":"平台速度慢"},{"classification_code":"V3-0199","project_name":"FMS","new_product":"GPS","case_nature":"安裝/維修作業","new_category":"GPS－施工/維修","new_subcategory":"購料"},{"classification_code":"V3-0200","project_name":"FMS","new_product":"GPS","case_nature":"安裝/維修作業","new_category":"GPS－施工/維修","new_subcategory":"寄送"},{"classification_code":"V3-0201","project_name":"FMS","new_product":"GPS","case_nature":"安裝/維修作業","new_category":"GPS－施工/維修","new_subcategory":"歸還"},{"classification_code":"V3-0202","project_name":"FMS","new_product":"行車視野","case_nature":"安裝/維修作業","new_category":"行車視野－施工/維修","new_subcategory":"購料"},{"classification_code":"V3-0203","project_name":"FMS","new_product":"行車視野","case_nature":"安裝/維修作業","new_category":"行車視野－施工/維修","new_subcategory":"寄送"},{"classification_code":"V3-0204","project_name":"FMS","new_product":"行車視野","case_nature":"安裝/維修作業","new_category":"行車視野－施工/維修","new_subcategory":"歸還"},{"classification_code":"V3-0205","project_name":"FMS","new_product":"行車視野","case_nature":"帳務/文件","new_category":"行車視野－帳務/文件","new_subcategory":"請款"},{"classification_code":"V3-0206","project_name":"FMS","new_product":"行車視野","case_nature":"帳務/文件","new_category":"行車視野－帳務/文件","new_subcategory":"匯款明細"},{"classification_code":"V3-0207","project_name":"FMS","new_product":"冷鏈","case_nature":"帳務/文件","new_category":"冷鏈－帳務/文件","new_subcategory":"請款"},{"classification_code":"V3-0208","project_name":"FMS","new_product":"冷鏈","case_nature":"帳務/文件","new_category":"冷鏈－帳務/文件","new_subcategory":"匯款明細"},{"classification_code":"V3-0209","project_name":"FMS","new_product":"雷達","case_nature":"帳務/文件","new_category":"雷達－帳務/文件","new_subcategory":"請款"},{"classification_code":"V3-0210","project_name":"FMS","new_product":"雷達","case_nature":"帳務/文件","new_category":"雷達－帳務/文件","new_subcategory":"匯款明細"},{"classification_code":"V3-0211","project_name":"FMS","new_product":"共通平台","case_nature":"帳務/文件","new_category":"共通平台－帳務/文件","new_subcategory":"請款"},{"classification_code":"V3-0212","project_name":"FMS","new_product":"共通平台","case_nature":"帳務/文件","new_category":"共通平台－帳務/文件","new_subcategory":"匯款明細"},{"classification_code":"V3-0213","project_name":"FMS","new_product":"GPS","case_nature":"查詢/協助","new_category":"GPS－查詢/操作","new_subcategory":"維修進度查詢"},{"classification_code":"V3-0214","project_name":"FMS","new_product":"行車視野","case_nature":"查詢/協助","new_category":"行車視野－查詢/操作","new_subcategory":"維修進度查詢"},{"classification_code":"V3-0215","project_name":"FMS","new_product":"冷鏈","case_nature":"查詢/協助","new_category":"冷鏈－查詢/操作","new_subcategory":"維修進度查詢"},{"classification_code":"V3-0216","project_name":"FMS","new_product":"雷達","case_nature":"查詢/協助","new_category":"雷達－查詢/操作","new_subcategory":"維修進度查詢"},{"classification_code":"V3-0217","project_name":"FMS","new_product":"共通平台","case_nature":"查詢/協助","new_category":"共通平台－查詢/操作","new_subcategory":"維修進度查詢"},{"classification_code":"V3-0218","project_name":"FMS","new_product":"GPS","case_nature":"故障/異常","new_category":"GPS報表/API","new_subcategory":"報表匯出緩慢"},{"classification_code":"V3-0219","project_name":"FMS","new_product":"冷鏈","case_nature":"故障/異常","new_category":"冷鏈報表/API","new_subcategory":"報表匯出緩慢"},{"classification_code":"V3-0220","project_name":"FMS","new_product":"冷鏈","case_nature":"安裝/維修作業","new_category":"冷鏈－溫度探棒/校正","new_subcategory":"探棒校正作業"}]$v31$::jsonb) t where p_record @> t)
        or (p_record->>'case_nature'='其他/待確認' and nullif(btrim(p_record->>'classification_note'),'') is null)
      ) then raise exception 'Active V3.1 classification tuple and project required'; end if;
      -- Only supplied real columns are inserted, preserving defaults for absent columns.
      -- Identifiers come from the catalog and are quoted; all values remain parameters.
      select string_agg(format('%I',a.attname),',' order by a.attnum),
             string_agg(format('r.%I',a.attname),',' order by a.attnum)
      into cols,vals from pg_attribute a where a.attrelid='public.cases'::regclass
        and a.attnum>0 and not a.attisdropped and a.attgenerated='' and a.attidentity=''
        and p_record ? a.attname;
      execute format('insert into public.cases(%s) select %s from jsonb_populate_record(null::public.cases,$1) r returning id',cols,vals)
        into target using p_record;
    elsif p_action='merge' then
      target := nullif(trim(p_case_id),'');
      perform 1 from public.cases where id=target for update;
      if not found then raise exception 'Target case unavailable'; end if;
      update public.cases set description=coalesce(description,'') || E'\n\n【LINE 對話串 ' || p_id::text || E'】\n' || transcript where id=target;
      get diagnostics changed=row_count;
      if changed<>1 then raise exception 'Case update denied'; end if;
    end if;
    update public.line_messages set status=case when p_action='archive' then 'archived' else 'linked' end,
      case_id=case when p_action='archive' then case_id else target end
      where id=any(actual);
    get diagnostics changed=row_count;
    if changed<>cardinality(actual) then raise exception 'Message update denied'; end if;
    update public.line_conversations set status=case when p_action='archive' then 'archived' else 'linked' end,
      primary_case_id=target,sealed=true,version=version+1 where id=p_id;
    get diagnostics changed=row_count;
    if changed<>1 then raise exception 'Conversation update denied'; end if;
  else raise exception 'Unsupported conversation action'; end if;
  insert into public.activity_log(case_id,action,changed_by,changed_at,detail)
    values(target,'LINE '||p_action,auth.uid()::text,now(),format('conversation=%s messages=%s split=%s',p_id,cardinality(actual),new_id));
  return jsonb_build_object('conversation_id',p_id,'case_id',target,'split_conversation_id',new_id);
end $$;
revoke all on function public.line_conversation_action(uuid,text,bigint,uuid[],text,uuid[],jsonb) from public,anon;
grant execute on function public.line_conversation_action(uuid,text,bigint,uuid[],text,uuid[],jsonb) to authenticated;
commit;
